-- Ribbon TERRAIN as REAL noise-driven map-gen (§4, §15-2; ci-3yl, reworked ci-da2,
-- rebuilt ci-wly, rebuilt again ci-oe83 as ONE CONTINUOUS ELEVATION FIELD).
--
-- The ribbon is generated by the MAP-GEN itself, not by an on_chunk_generated script.
-- This module is the single source of truth for the tile layout.
--
-- 🚨 ONE HEIGHTMAP, NOT THREE (ci-oe83). The planet is driven by ONE continuous
-- elevation field E across the WHOLE perpendicular axis: a smooth valley, LOW in the
-- habitable middle and rising toward BOTH edges (a single monotonic ramp + one shared
-- basis-noise). The THREE regions -- HOT (sunward / +perp), habitable MIDDLE, COLD
-- (nightward / -perp) -- are just three different APPLICATIONS of that one field:
--
--   * where E is HIGH on the SUNWARD half -> the HOT ring order (ash-dark -> smooth-
--     stone -> cracks -> cracks-warm -> cracks-hot -> smooth-stone-warm -> lava ->
--     lava-hot), the hottest tiles at the highest elevation;
--   * where E is HIGH on the NIGHTWARD half -> the COLD ring order (ash-light -> dust
--     -> snow -> rough-ice -> smooth-ice), the coldest tiles at the highest elevation;
--   * where E is LOW (the middle trough) -> the ash MIX + soil patches.
--
-- BOTH OCEANS EMERGE FROM THE ONE FIELD (ci-oe83 fix). The lava ocean and the ice
-- ocean are simply the two EXTREMES of E: lava-hot / ice-smooth are the open-top
-- rings that win wherever E crosses their threshold. There is NO forced sea floor, NO
-- fixed-width ocean ZONE, NO steep perpendicular gate confining the ocean, and NO
-- per-region heightmap. The ocean is continuous with the rings in front of it (E is a
-- smooth ramp + one noise, with no discontinuity), so it is never "stamped on top" of
-- a finished map, and its ~200-tile extent EMERGES from where the ramp crosses the
-- lava threshold -- remove the positional ocean ZONE and the ocean still generates,
-- because it is the field's peak, not a hardcoded band.
--
-- DAMAGE keys off the CONTINUOUS FIELD, not the tile under the entity (ci-oe83,
-- realigning the code with DESIGN §3: positional lethal-zone damage). M.field_damage
-- maps the perpendicular coordinate to a monotonic heat/cold intensity that ramps
-- from 0 at the damage onset (the hot/cold region inner edge) up to full at the ocean.
-- Because the elevation ramp is tuned so lava/ice can only EMERGE well beyond the
-- damage onset, there is NO non-damaging walkable path from the safe middle to any
-- lava tile: you always cross the damaging band first (proven by the ci-oe83 repro
-- flood-fill guard in tests/test_worldgen.lua). This is the same positional field the
-- resource band masks (scripts/resource-field.lua) and the screen tint
-- (scripts/damage-feedback.lua) read, so damage, feedback and resources share ONE
-- axis-of-truth.
--
-- WIDTHS. Each zone width is a mod setting (settings.lua); the TOTAL is the SUM.
-- Defaults sum to 800 with the hot side (200+70+70) equal to the cold side, so the
-- 120-wide MIDDLE straddles the origin (spawn). The zone bands are POSITIONAL
-- descriptors -- they mark WHERE the damage onset, resource keep-back and solar
-- anchors sit -- they no longer force any tile; the ocean/rings emerge from E.
--
-- WALKABILITY is per-TILE. Only the two lava tiles are impassable (molten fluid), so
-- the hot-lava ocean is the one hard WALL. The smooth-ice ocean is WALKABLE (you can
-- RUN on it, the field just freezes you). Every other tile is buildable ground.
--
-- NO-PAVE HAZARD TILES (ci-wly, extends ci-cbn, closes ci-8vu): you cannot pave atop
-- M.NO_PAVE (the hottest / iciest hazards); scripts/no-paving.lua reverts any tile
-- built on one on the cindra surface.
--
-- The world is finite PERPENDICULAR via the map-gen's own `width`/`height`.
--
-- PURE where it counts: the zone table, band geometry, the ring orders + elevation
-- ramp, the ring/middle membership, the probability/field-damage emitters and the
-- bounds are plain string/table logic (no game.* / prototypes.*), unit-testable off
-- the game (unit-tests/test_terrain.lua).

local axis = require("scripts.axis")

local M = {}

-- ---------------------------------------------------------------------------
-- The ordered Cindra POSITIONAL zones, HOT (west, +perp) -> COLD (east, -perp). These
-- are the positional descriptors used for band geometry, resource banding, damage
-- onset and solar anchors. They no longer FORCE any tile -- the tiles + oceans emerge
-- from the one elevation field (M.probability_expr). Fields:
--   role     stable key for geometry helpers, settings + resource banding.
--   width    default band width in tiles (the mod-setting default).
--   setting  the per-zone width mod-setting name (settings.lua).
--   region   "hot" | "middle" | "cold": which application of the field paints here.
--   ocean    true => the OUTER band where the field peaks into its ocean.
--   wall     true => the outer hot band (the lava ocean is the one hard wall).
--   damage   "heat" | "cold" | nil: the environmental damage this BAND marks
--            (positional descriptor; see M.damage_bounds / M.field_damage).
-- ---------------------------------------------------------------------------
M.ZONES = {
  { role = "hot_ocean",  width = 200, setting = "cindra-zone-width-hot-ocean",
    region = "hot", ocean = true, wall = true, damage = "heat" },
  { role = "hot_inner",  width = 70,  setting = "cindra-zone-width-hot-inner",
    region = "hot", damage = "heat" },
  { role = "hot_outer",  width = 70,  setting = "cindra-zone-width-hot-outer",
    region = "hot" },
  { role = "middle",     width = 120, setting = "cindra-zone-width-middle",
    region = "middle" },
  { role = "cold_outer", width = 70,  setting = "cindra-zone-width-cold-outer",
    region = "cold" },
  { role = "cold_inner", width = 70,  setting = "cindra-zone-width-cold-inner",
    region = "cold", damage = "cold" },
  { role = "cold_ocean", width = 200, setting = "cindra-zone-width-cold-ocean",
    region = "cold", ocean = true, damage = "cold" },
}

-- The index of the wide safe MIDDLE band (spawn).
M.BUILDING_ROLE = "middle"
local BUILDING_INDEX
for i, z in ipairs(M.ZONES) do
  if z.role == M.BUILDING_ROLE then BUILDING_INDEX = i end
end

-- The cindra-* tile name for a vanilla clone source (deterministic prefix).
local function cindra_name(vanilla) return "cindra-" .. vanilla end
M.cindra_name = cindra_name

-- ---------------------------------------------------------------------------
-- The ONE elevation field's ring orders (highest E first = the ocean CORE, down to
-- the lowest tile that hands off to the ash middle). `lo` is the ring's LOWER
-- elevation threshold; its upper threshold is the previous ring's `lo`. The tile whose
-- band contains E wins, so equal-E contours nest as concentric rings. The OCEAN tile
-- is the open-top CORE (hi = +inf), so wherever the ramp+noise crosses its threshold
-- the ocean fills solid -- an EMERGENT sea, not a forced floor. Both orders span the
-- WHOLE of their side (from the middle edge out to the ocean); there is no separate
-- flat outer slope and no per-region heightmap -- it is one field, two applications.
--
-- Elevation units: the ramp peaks at HEIGHT_PEAK (100) at the map edge and is 0 at the
-- middle edge (negative inside the middle), so the thresholds below read as "percent
-- of the way from the middle edge to the map edge" plus the shared noise.
-- ---------------------------------------------------------------------------
local RING_BIG = 1e9

-- HOT ring order (sunward): ash-dark (blends to the middle) -> ... -> lava-hot (the
-- open-top ocean core). The damaging ART (cracks-hot, smooth-stone-warm, lava) sits
-- at the higher elevations, which the ramp places beyond the perpendicular damage
-- onset; the field-damage (not these tiles) is what actually burns.
M.HOT_RING_ORDER = {
  { vanilla = "lava-hot",                   lo = 68 },        -- molten CORE / ocean peak (open top)
  { vanilla = "lava",                       lo = 38 },        -- molten body
  { vanilla = "volcanic-smooth-stone-warm", lo = 26 },        -- warm crust ring, adjacent to lava
  { vanilla = "volcanic-cracks-hot",        lo = 17 },        -- glowing cracks ring
  { vanilla = "volcanic-cracks-warm",       lo = 10 },        -- warm cracks (the edge-push margin)
  { vanilla = "volcanic-cracks",            lo = 5 },         -- cool cracks (safe slope)
  { vanilla = "volcanic-smooth-stone",      lo = 1 },         -- cool smooth stone (safe slope)
  { vanilla = "volcanic-ash-dark",          lo = -8 },        -- lowest, blends to the ash middle
}

-- COLD ring order (nightward mirror): ash-light -> dust -> snow -> rough-ice ->
-- ice-smooth (the open-top ocean core). Same shared elevation field, cold family.
M.COLD_RING_ORDER = {
  { vanilla = "ice-smooth",  lo = 68 },        -- frozen CORE / ocean peak (open top)
  { vanilla = "ice-rough",   lo = 38 },        -- rough ice, ringing the smooth cap
  { vanilla = "snow-patchy", lo = 26 },        -- deep snow
  { vanilla = "snow-lumpy",  lo = 17 },
  { vanilla = "snow-crests", lo = 11 },
  { vanilla = "snow-flat",   lo = 6 },
  { vanilla = "dust-patchy", lo = 1 },         -- first ring above the middle
  { vanilla = "dust-lumpy",  lo = -4 },
  { vanilla = "dust-crests", lo = -8 },
  { vanilla = "dust-flat",   lo = -12 },
  { vanilla = "volcanic-ash-light", lo = -16 },-- lowest, blends to the ash middle
}

-- The elevation ABOVE which the rings take over from the ash middle (both sides). At
-- or below MID_TOP the middle mix wins; above it the lowest ring (hot smooth-stone /
-- cold dust-patchy, both lo = 1) wins. This is the elevation-driven handoff between the
-- middle application and the ring applications -- NOT a perpendicular gate.
M.MID_TOP = 1

-- SOIL patches: a mini ring model on a low-frequency PATCH field, confined to the
-- middle (by the SAME elevation handoff, not a perp gate). soil-dark at a patch centre,
-- ringed by soil-light, then ash-soil, blending back to the ash mix.
M.SOIL_RING_ORDER = {
  { vanilla = "volcanic-soil-dark",  lo = 20 },  -- patch centre (highest patch elevation)
  { vanilla = "volcanic-soil-light", lo = 14 },  -- ring around the dark core
  { vanilla = "volcanic-ash-soil",   lo = 8 },   -- outer ring, blends to the ash mix
}

-- The habitable MIDDLE mix (the low-elevation trough): even-weighted ash tiles; the
-- per-tile speckle interpenetrates them into an organic mix. Soil is a separate patch
-- ring layered on top.
M.MIDDLE_MIX = { "volcanic-ash-dark", "volcanic-ash-light", "volcanic-ash-flats" }

-- The NO-PAVE hazard set (ci-wly): the hottest / iciest hazards. Blocking paving here
-- keeps the lethal ground lethal and closes the ci-8vu lava-pump exploit.
M.NO_PAVE_VANILLA = {
  "lava-hot", "lava", "volcanic-smooth-stone-warm", "volcanic-cracks-hot",
  "ice-smooth", "ice-rough",
}

-- Impassable tiles: only the two lava tiles (molten fluid). smooth-ice is WALKABLE.
local IMPASSABLE = { ["lava-hot"] = true, ["lava"] = true }

M.NO_PAVE = {}
for _, vanilla in ipairs(M.NO_PAVE_VANILLA) do M.NO_PAVE[cindra_name(vanilla)] = true end

-- True if a tile is in the NO-PAVE hazard set (scripts/no-paving.lua reads this).
function M.is_no_pave(name) return M.NO_PAVE[name] == true end

-- ---------------------------------------------------------------------------
-- The concrete TILES (deduplicated), ordered hot -> cold, and the membership tables.
-- ---------------------------------------------------------------------------

-- A hot -> cold map-view colour ramp (ci-4h7): reds sunward, a dark ash belt at the
-- middle, pale cyan/frost nightward. `t` is the normalised gradient position (0 hottest,
-- 1 coldest). Kept in lockstep with gen-planet-maps.py.
local COLOR_STOPS = {
  { 0.00, { 0.98, 0.42, 0.06 } }, -- lava, orange-red
  { 0.18, { 0.80, 0.30, 0.10 } }, -- molten crust
  { 0.34, { 0.45, 0.32, 0.24 } }, -- warm volcanic brown (fire -> middle)
  { 0.46, { 0.243, 0.165, 0.125 } }, -- dark volcanic-ash middle #3E2A20
  { 0.54, { 0.255, 0.196, 0.157 } }, -- ash middle #41322A
  { 0.66, { 0.42, 0.42, 0.44 } }, -- cooling dust-grey (middle -> ice)
  { 0.80, { 0.66, 0.82, 0.88 } }, -- pale frost
  { 1.00, { 0.82, 0.95, 1.00 } }, -- icy white-blue
}
local function ramp_color(t)
  if t <= COLOR_STOPS[1][1] then return COLOR_STOPS[1][2] end
  for i = 2, #COLOR_STOPS do
    local a, b = COLOR_STOPS[i - 1], COLOR_STOPS[i]
    if t <= b[1] then
      local f = (t - a[1]) / (b[1] - a[1])
      local ca, cb = a[2], b[2]
      return { ca[1] + (cb[1] - ca[1]) * f, ca[2] + (cb[2] - ca[2]) * f, ca[3] + (cb[3] - ca[3]) * f }
    end
  end
  return COLOR_STOPS[#COLOR_STOPS][2]
end

M.TILES = {}
local TILE_BY_NAME = {}        -- cindra name -> tile entry
local HOT_RING_BAND = {}       -- cindra name -> { lo, hi } hot elevation band
local COLD_RING_BAND = {}      -- cindra name -> { lo, hi } cold elevation band
local SOIL_RING_BAND = {}      -- cindra name -> { lo, hi } soil patch band
local MIDDLE_MEMBER = {}       -- cindra name -> true if an ash-middle mix tile
local GRADIENT_POS = {}        -- cindra name -> normalised 0..1 hot->cold position

local function build_bands(order, dst)
  local prev_hi = RING_BIG
  for _, r in ipairs(order) do
    dst[cindra_name(r.vanilla)] = { lo = r.lo, hi = prev_hi }
    prev_hi = r.lo
  end
end
build_bands(M.HOT_RING_ORDER, HOT_RING_BAND)
build_bands(M.COLD_RING_ORDER, COLD_RING_BAND)
build_bands(M.SOIL_RING_ORDER, SOIL_RING_BAND)
M.ring_band_hot = HOT_RING_BAND
M.ring_band_cold = COLD_RING_BAND

do
  local order = {}
  local function register(vanilla, gradient_pos)
    local name = cindra_name(vanilla)
    if not TILE_BY_NAME[name] then
      local entry = { name = name, clone_from = vanilla, walkable = not IMPASSABLE[vanilla] }
      TILE_BY_NAME[name] = entry
      order[#order + 1] = entry
      GRADIENT_POS[name] = gradient_pos
    elseif gradient_pos ~= nil and GRADIENT_POS[name] == nil then
      GRADIENT_POS[name] = gradient_pos
    end
    return name
  end

  -- Hot rings CORE -> outer: gradient 0 (lava-hot) -> ~0.47 (ash-dark).
  local nh = #M.HOT_RING_ORDER
  for i, r in ipairs(M.HOT_RING_ORDER) do register(r.vanilla, 0.47 * (i - 1) / (nh - 1)) end
  -- Middle ash mix + soil (the dark ash belt ~0.5).
  register("volcanic-ash-flats", 0.50)
  register("volcanic-ash-soil", 0.50); register("volcanic-soil-light", 0.50); register("volcanic-soil-dark", 0.50)
  -- Cold rings OUTER -> CORE (coldest last): gradient ~0.53 (ash-light) -> 1.0 (ice-smooth).
  local nc = #M.COLD_RING_ORDER
  for i = nc, 1, -1 do register(M.COLD_RING_ORDER[i].vanilla, 1.0 - 0.47 * (i - 1) / (nc - 1)) end

  -- Mark the ash-middle mix members.
  for _, vanilla in ipairs(M.MIDDLE_MIX) do
    MIDDLE_MEMBER[cindra_name(vanilla)] = true
  end

  for _, entry in ipairs(order) do entry.map_color = ramp_color(GRADIENT_POS[entry.name] or 0.5) end
  M.TILES = order
end

-- Single-source-of-truth cross-checks.
for name in pairs(M.NO_PAVE) do
  if not TILE_BY_NAME[name] then error("terrain: no-pave tile " .. name .. " is not a registered tile") end
end

-- ---------------------------------------------------------------------------
-- Noise + elevation tuning.
-- ---------------------------------------------------------------------------
-- Middle-mix boundary wiggle + speckle. NOISE_AMPLITUDE / SPECKLE_AMPLITUDE are read
-- by scripts/resource-field.lua for its keep-back margin, so keep them small + stable.
M.NOISE_AMPLITUDE = 2
M.NOISE_WAVELENGTH = 14
M.SPECKLE_AMPLITUDE = 1.5
M.SPECKLE_WAVELENGTH = 4
M.PLATEAU = 1000          -- the shared positive base every placement term sits on
M.MIX_WEIGHT = 3          -- the ash-middle mix's edge over the lowest rings
M.SOIL_WEIGHT = 6         -- soil's edge over the ash mix where a patch is present

-- The ONE elevation field: a linear ramp from 0 at the region inner edge (the middle
-- edge) to HEIGHT_PEAK at the map edge, plus ONE shared basis-noise (the same seed on
-- both sides -> one continuous field). Lava/ice EMERGE where ramp+noise crosses the
-- ocean-core threshold; the noise amplitude is bounded so lava can only appear well
-- beyond the perpendicular damage onset (no non-damaging corridor -- see M.field_damage).
M.HEIGHT_PEAK = 100
M.HEIGHT_NOISE_AMPLITUDE = 12
M.HEIGHT_NOISE_WAVELENGTH = 44
M.ELEV_SEED = 42

-- Soil patch field.
M.SOIL_AMPLITUDE = 26
M.SOIL_WAVELENGTH = 22
M.SOIL_SEED = 50

-- The cindra tile a HOT elevation E falls in (pure). Off-game unit-testable.
function M.ring_tile_at(E)
  for _, r in ipairs(M.HOT_RING_ORDER) do
    if E >= r.lo then return cindra_name(r.vanilla) end
  end
  return nil
end
-- The cindra tile a COLD elevation E falls in.
function M.cold_ring_tile_at(E)
  for _, r in ipairs(M.COLD_RING_ORDER) do
    if E >= r.lo then return cindra_name(r.vanilla) end
  end
  return nil
end

local function clamp01(x)
  if x < 0 then return 0 elseif x > 1 then return 1 end
  return x
end

local function num(v)
  if v == math.floor(v) then return string.format("%d", v) end
  return string.format("%.6g", v)
end

-- ---------------------------------------------------------------------------
-- Zone widths + band geometry (PURE).
-- ---------------------------------------------------------------------------
function M.widths(cfg)
  cfg = cfg or {}
  local s = settings and settings.startup
  local out = {}
  for i, z in ipairs(M.ZONES) do
    local w = cfg[z.role]
    if w == nil and s and s[z.setting] then w = s[z.setting].value end
    if w == nil then w = z.width end
    out[i] = w
  end
  return out
end

-- The signed perpendicular band [lo, hi] (sunward-positive p, hot = high p) per zone,
-- centred on the origin (hot edge +TOTAL/2). Returns (bands, total).
function M.bands(cfg)
  local w = M.widths(cfg)
  local total = 0
  for _, v in ipairs(w) do total = total + v end
  local bands = {}
  local p = total / 2
  for i = 1, #w do
    bands[i] = { lo = p - w[i], hi = p }
    p = p - w[i]
  end
  return bands, total
end

function M.role_band(role, cfg)
  local bands = M.bands(cfg)
  for i, z in ipairs(M.ZONES) do
    if z.role == role then return bands[i] end
  end
  return nil
end

-- The perpendicular band spanned by a set of regions = the union of their zone bands.
local function region_band(regions, cfg)
  local bands = M.bands(cfg)
  local lo, hi
  for i, z in ipairs(M.ZONES) do
    if regions[z.region] then
      if lo == nil or bands[i].lo < lo then lo = bands[i].lo end
      if hi == nil or bands[i].hi > hi then hi = bands[i].hi end
    end
  end
  return { lo = lo, hi = hi }
end

-- The perpendicular band spanned by the HOT region (all hot zones). The hot ring
-- application paints here; the ocean emerges at its high-elevation (sunward) end.
function M.hot_region(cfg) return region_band({ hot = true }, cfg) end
-- The perpendicular band spanned by the COLD region.
function M.cold_region(cfg) return region_band({ cold = true }, cfg) end

local function ocean_band(region, cfg)
  local bands = M.bands(cfg)
  for i, z in ipairs(M.ZONES) do
    if z.region == region and z.ocean then return bands[i] end
  end
  return nil
end

-- The perp-axis boundaries scripts/resource-field.lua bands resources against.
function M.resource_bounds(cfg)
  local bands = M.bands(cfg)
  local b = bands[BUILDING_INDEX]
  local hot_edge = b.hi
  for i = BUILDING_INDEX - 1, 1, -1 do
    if not M.ZONES[i].wall then hot_edge = bands[i].hi else break end
  end
  return {
    building_half = b.hi,
    building_lo = b.lo,
    hot_edge = hot_edge,
    cold_edge = bands[#bands].lo,
  }
end

-- The perpendicular band spanned by the VOLCANIC rocky zones (hot inner + hot outer),
-- where burned volcanic rocks scatter. Excludes the lava ocean, middle and cold side.
M.CLIFF_ROLES = { "hot_inner", "hot_outer" }
function M.cliff_band(cfg)
  local lo, hi
  for _, role in ipairs(M.CLIFF_ROLES) do
    local b = M.role_band(role, cfg)
    if b then
      if lo == nil or b.lo < lo then lo = b.lo end
      if hi == nil or b.hi > hi then hi = b.hi end
    end
  end
  return { lo = lo, hi = hi }
end

-- The positional DAMAGE bounds (band edges where the field damage turns on).
function M.damage_bounds(cfg)
  local bands = M.bands(cfg)
  local hot_from, cold_from
  for i, z in ipairs(M.ZONES) do
    if z.damage == "heat" then
      if hot_from == nil or bands[i].lo < hot_from then hot_from = bands[i].lo end
    elseif z.damage == "cold" then
      if cold_from == nil or bands[i].hi > cold_from then cold_from = bands[i].hi end
    end
  end
  return { hot_from = hot_from, cold_from = cold_from }
end

-- Which environmental damage ("heat"/"cold"/nil) is dealt at perpendicular coord `p`.
function M.lethal_at(p, cfg)
  local b = M.damage_bounds(cfg)
  if b.hot_from and p >= b.hot_from then return "heat" end
  if b.cold_from and p <= b.cold_from then return "cold" end
  return nil
end

-- ---------------------------------------------------------------------------
-- CONTINUOUS FIELD DAMAGE (ci-oe83). The environment's lethality is a monotonic
-- function of the PERPENDICULAR coordinate -- the same one axis the ocean's elevation
-- rises along -- NOT a per-tile-type lookup. It ramps from 0 at the region inner edge
-- (the damage onset) up to 1.0 at the ocean inner edge, then holds 1.0 across the
-- ocean, so it is monotonic toward the ocean on both sides. Because the elevation ramp
-- only lets lava/ice EMERGE beyond the damage onset, every path from the safe middle to
-- a lava tile crosses the damaging band first (the corridor is closed by the field, not
-- by which tile art is underfoot). PURE: pass a cfg for determinism off-game.
--   returns (intensity 0..1, kind "heat"|"cold"|nil)
-- ---------------------------------------------------------------------------
function M.field_damage(p, cfg)
  local which = M.lethal_at(p, cfg)
  if not which then return 0, nil end
  local b = M.damage_bounds(cfg)
  if which == "heat" then
    local full = ocean_band("hot", cfg).lo       -- full damage from the hot ocean inner edge
    local span = full - b.hot_from
    local t = span > 0 and (p - b.hot_from) / span or 1
    return clamp01(t), "heat"
  else
    local full = ocean_band("cold", cfg).hi       -- full damage from the cold ocean inner edge
    local span = b.cold_from - full
    local t = span > 0 and (b.cold_from - p) / span or 1
    return clamp01(t), "cold"
  end
end

-- ---------------------------------------------------------------------------
-- The ONE elevation ramp (PURE, deterministic component; the noise is added in the
-- noise-expression). E_ramp(p) is a smooth valley: 0 at the region inner edge (middle
-- edge), rising LINEARLY to HEIGHT_PEAK at the map edge on each side, and negative
-- inside the middle. It is CONTINUOUS everywhere including across the ocean boundary
-- (no forced-floor step) -- the ci-oe83 continuity guarantee. Used by tests to prove
-- continuity and to locate the emergent ocean.
--   side: "hot" (sunward) or "cold" (nightward).
-- ---------------------------------------------------------------------------
local function ramp_anchors(side, cfg)
  local _, total = M.bands(cfg)
  local half = total / 2
  local mid = M.role_band("middle", cfg)
  local inner = (side == "cold") and -mid.lo or mid.hi
  local span = math.max(1, half - inner)
  return inner, span
end

function M.elevation_ramp(p, side, cfg)
  local inner, span = ramp_anchors(side, cfg)
  local out = (side == "cold") and (-p) or p
  return M.HEIGHT_PEAK * (out - inner) / span
end

-- The nominal perpendicular position (no noise) at which a HOT elevation E occurs.
function M.hot_perp_at_elevation(E, cfg)
  local inner, span = ramp_anchors("hot", cfg)
  return inner + E * span / M.HEIGHT_PEAK
end

-- ---------------------------------------------------------------------------
-- Noise-expression emitters.
-- ---------------------------------------------------------------------------
local function basis(seed1, amp, wl)
  return "basis_noise{x = x, y = y, seed0 = 1, seed1 = " .. num(seed1) ..
         ", input_scale = " .. num(1 / wl) .. ", output_scale = " .. num(amp) .. "}"
end
local function speckle_noise(tile_index) return basis(100 + tile_index, M.SPECKLE_AMPLITUDE, M.SPECKLE_WAVELENGTH) end
local function elevation_noise() return basis(M.ELEV_SEED, M.HEIGHT_NOISE_AMPLITUDE, M.HEIGHT_NOISE_WAVELENGTH) end

local function relu(expr) return "max(0, " .. expr .. ")" end

-- The ONE elevation field E for a side as a noise-expression string: the linear ramp
-- (0 at the middle edge, HEIGHT_PEAK at the map edge) + the ONE shared elevation noise.
-- No forced sea floor, no gate -- just a smooth ramp + noise, so the field (and the
-- ocean at its peak) is continuous with the terrain in front of it.
local function elevation_expr(side, cfg)
  local inner, span = ramp_anchors(side, cfg)
  local out = (side == "cold") and axis.perp_neg_expr() or axis.perp_expr()
  local ramp = num(M.HEIGHT_PEAK) .. " * ((" .. out .. ") - " .. num(inner) .. ") / " .. num(span)
  return "(" .. ramp .. " + " .. elevation_noise() .. ")"
end

-- One ring PLACEMENT term for a tile on one side: PLATEAU minus how far the field E is
-- OUTSIDE the tile's elevation band [lo, hi]. Highest (= PLATEAU) exactly where E is in
-- the band; falls off with distance so the in-band ring wins. The ocean core has an
-- open top (hi = RING_BIG), so it stays at PLATEAU across the whole sea.
local function ring_term(E, band)
  local below = relu(num(band.lo) .. " - " .. E)
  local above = (band.hi >= RING_BIG) and "0" or relu(E .. " - " .. num(band.hi))
  return num(M.PLATEAU) .. " - (" .. below .. " + " .. above .. ")"
end

-- The MIDDLE mix term for an ash tile: PLATEAU + the mix weight, minus how far EITHER
-- side's field rises above MID_TOP (so the middle loses to the rings once the field
-- climbs into the ocean's slope). Elevation-arbitrated, not a perpendicular gate.
local function middle_term(E_hot, E_cold)
  local fall = relu(E_hot .. " - " .. num(M.MID_TOP)) .. " + " .. relu(E_cold .. " - " .. num(M.MID_TOP))
  return num(M.PLATEAU) .. " + " .. num(M.MIX_WEIGHT) .. " - (" .. fall .. ")"
end

-- One SOIL patch ring term: like the middle term (confined to the low-elevation trough
-- by the SAME elevation handoff), plus a soil-patch selector on the low-frequency soil
-- field so soil only wins where a patch is present.
local function soil_term(E_hot, E_cold, band)
  local soilE = basis(M.SOIL_SEED, M.SOIL_AMPLITUDE, M.SOIL_WAVELENGTH)
  local sel = relu(num(band.lo) .. " - " .. soilE) .. " + " .. relu(soilE .. " - " .. num(band.hi))
  local fall = relu(E_hot .. " - " .. num(M.MID_TOP)) .. " + " .. relu(E_cold .. " - " .. num(M.MID_TOP))
  return num(M.PLATEAU) .. " + " .. num(M.SOIL_WEIGHT) .. " - (" .. sel .. " + " .. fall .. ")"
end

-- The `probability_expression` for a Cindra tile: the MAX over its placement terms + a
-- speckle. A tile can carry a HOT ring term, a COLD ring term, a MIDDLE mix term,
-- and/or a SOIL patch term. The engine places the highest-probability tile per point,
-- so the ocean/rings/middle all emerge from the ONE elevation field.
function M.probability_expr(name, cfg)
  local tile, index
  for i, t in ipairs(M.TILES) do
    if t.name == name then tile = t; index = i; break end
  end
  if not tile then error("terrain: unknown Cindra tile " .. tostring(name)) end

  local E_hot = elevation_expr("hot", cfg)
  local E_cold = elevation_expr("cold", cfg)
  local terms = {}

  local hband = HOT_RING_BAND[name]
  if hband then terms[#terms + 1] = ring_term(E_hot, hband) end

  local cband = COLD_RING_BAND[name]
  if cband then terms[#terms + 1] = ring_term(E_cold, cband) end

  if MIDDLE_MEMBER[name] then terms[#terms + 1] = middle_term(E_hot, E_cold) end

  local sband = SOIL_RING_BAND[name]
  if sband then terms[#terms + 1] = soil_term(E_hot, E_cold, sband) end

  if #terms == 0 then error("terrain: tile " .. name .. " has no placement term") end
  local expr = terms[1]
  for i = 2, #terms do expr = "max(" .. expr .. ", " .. terms[i] .. ")" end
  -- A per-tile speckle interpenetrates co-present members so shared boundaries mix.
  return "(" .. expr .. ") + " .. speckle_noise(index)
end

function M.map_color(name)
  local t = TILE_BY_NAME[name]
  return t and t.map_color or nil
end

function M.is_walkable(name)
  local t = TILE_BY_NAME[name]
  if t == nil then return nil end
  return t.walkable
end

-- The set of member tile names (cindra-*) of a zone role, as a set { name = true }: the
-- tiles a point in that zone's band can be painted with (its region's ring set, plus the
-- ash mix + soil for the middle).
function M.zone_tiles(role)
  local out = {}
  local zone
  for _, z in ipairs(M.ZONES) do if z.role == role then zone = z end end
  if not zone then return out end
  if zone.region == "hot" then
    for _, r in ipairs(M.HOT_RING_ORDER) do out[cindra_name(r.vanilla)] = true end
  elseif zone.region == "cold" then
    for _, r in ipairs(M.COLD_RING_ORDER) do out[cindra_name(r.vanilla)] = true end
  else -- the middle
    for _, v in ipairs(M.MIDDLE_MIX) do out[cindra_name(v)] = true end
    for _, r in ipairs(M.SOIL_RING_ORDER) do out[cindra_name(r.vanilla)] = true end
  end
  return out
end

function M.tile_zones(name)
  local out = {}
  for _, z in ipairs(M.ZONES) do
    if M.zone_tiles(z.role)[name] then out[z.role] = true end
  end
  return out
end

function M.tile_names()
  local out = {}
  for _, t in ipairs(M.TILES) do out[#out + 1] = t.name end
  return out
end

function M.finite_dimension(cfg)
  local _, total = M.bands(cfg)
  return {
    key = (axis.orientation() == axis.HORIZONTAL) and "height" or "width",
    value = total,
  }
end

return M
